class DownloadWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
    override suspend fun doWork(): Result {
        val path = download(inputData.getString("url") ?: return Result.failure())
        return Result.success(workDataOf("path" to path))   // becomes ProcessWorker's input
    }
}

WorkManager.getInstance(context)
    .beginWith(OneTimeWorkRequestBuilder<DownloadWorker>().build())
    .then(OneTimeWorkRequestBuilder<ProcessWorker>().build())
    .then(OneTimeWorkRequestBuilder<UploadWorker>().build())
    .enqueue()

val request = OneTimeWorkRequestBuilder<SendMessageWorker>()
    .setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST)
    .build()

class SendMessageWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
    override suspend fun doWork(): Result { send(); return Result.success() }

    // Used on Android 11 and lower, where expedited work runs as a foreground service
    override suspend fun getForegroundInfo() = ForegroundInfo(NOTIFICATION_ID, buildNotification())
}
